(function(){
'use strict';
// The shared camera installs its base style at runtime; keep preview/mobile overrides last.
document.head.appendChild(document.querySelector('link[rel=stylesheet]'));
const $=s=>document.querySelector(s),input=$('#preview-file'),canvas=$('#image-preview'),ctx=canvas.getContext('2d',{willReadFrequently:true,colorSpace:'srgb'}),core=window.ATLAS_LIVE_CAMERA_CORE,binder=core.create(window.ATLAS_CLARUS_DATA);let file=null,pending=null,url=null,sequence=0,hasImage=false;
for(const [id,view] of Object.entries(window.ATLAS_CLARUS_DATA.views)){if(!view.hidden_from_new_selection)$('#library-view').add(new Option(view.name,id));}$('#library-view').value='core';
const canCapture=window.isSecureContext&&!!navigator.mediaDevices?.getUserMedia;
$('#start-camera').disabled=!canCapture;
if(!canCapture)$('#capability').textContent='Live-Kamera nicht verfügbar. Bitte über HTTPS in Safari oder Chrome öffnen oder ein Bild auswählen.';
$('#start-camera').onclick=()=>window.ATLAS_LIVE_CAMERA.open(input);
function download(name,blob){const link=document.createElement('a'),u=URL.createObjectURL(blob);link.href=u;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(u),1500);}
function sample(x,y){if(!hasImage)return;const left=Math.max(0,x-5),top=Math.max(0,y-5),right=Math.min(canvas.width-1,x+5),bottom=Math.min(canvas.height-1,y+5);const rgb=core.mean(ctx.getImageData(left,top,right-left+1,bottom-top+1).data),match=binder.match(rgb,binder.library($('#library-view').value)),record={schema:'atlas-clarus-browser-photo-sample/1.0',...match,sampling:{mode:'AREA_MEAN_RGB',bounds:[left,top,right,bottom],width:canvas.width,height:canvas.height},source_name:file.name,status:'PHOTO_ESTIMATE'};
const card=document.createElement('div');card.className='sample-record';card.style.setProperty('--sample',match.source_hex);const title=document.createElement('strong');title.textContent=match.source_hex+' → '+match.atlas_reference;const values=document.createElement('p');values.textContent='Referenz '+match.reference_hex+' · Row '+match.atlas_row_id;const detail=document.createElement('small');detail.textContent=match.library_name+' · RGB-Nächste-Referenz · keine physische Farbmessung';const save=document.createElement('button');save.textContent='Bild speichern';save.onclick=()=>download(file.name,file);const evidence=document.createElement('button');evidence.textContent='Farbnachweis speichern';evidence.onclick=async()=>{const digest=await crypto.subtle.digest('SHA-256',await file.arrayBuffer());download('ATLAS_Photo_Sample.json',new Blob([JSON.stringify({...record,image_sha256:[...new Uint8Array(digest)].map(v=>v.toString(16).padStart(2,'0')).join('')},null,2)],{type:'application/json'}));};card.append(title,values,detail,save,evidence);$('#photo-sample').replaceChildren(card);}
input.addEventListener('change',()=>{const next=input.files[0];if(!next)return;const token=++sequence;file=next;pending=null;hasImage=false;$('#empty').hidden=true;$('#result').hidden=false;$('#selection').replaceChildren();$('#photo-sample').replaceChildren();$('#image-status').textContent='Bild wird geöffnet …';if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(file);const image=new Image();image.onload=()=>{if(token!==sequence)return;canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;ctx.drawImage(image,0,0);hasImage=true;$('#image-status').textContent='Bild übernommen · '+canvas.width+' × '+canvas.height+' px. Zum Erkunden auf das Bild tippen.';if(!pending)sample(Math.floor(canvas.width/2),Math.floor(canvas.height/2));};image.onerror=()=>{if(token===sequence)$('#image-status').textContent='Dieses Bild konnte nicht geöffnet werden. Bitte ein anderes Foto wählen.';};image.src=url;});
input.addEventListener('atlas-camera-selection',e=>{pending=e.detail;const card=document.getElementById('atlas-camera-record-preview-file');if(card)$('#selection').replaceChildren(card);$('#photo-sample').replaceChildren();});
canvas.onclick=e=>{if(!hasImage)return;const rect=canvas.getBoundingClientRect(),scale=Math.min(rect.width/canvas.width,rect.height/canvas.height),w=canvas.width*scale,h=canvas.height*scale,ox=(rect.width-w)/2,oy=(rect.height-h)/2;const x=Math.floor((e.clientX-rect.left-ox)/scale),y=Math.floor((e.clientY-rect.top-oy)/scale);if(x>=0&&y>=0&&x<canvas.width&&y<canvas.height)sample(x,y);};
canvas.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();sample(Math.floor(canvas.width/2),Math.floor(canvas.height/2));}};
$('#library-view').onchange=()=>{if(hasImage)sample(Math.floor(canvas.width/2),Math.floor(canvas.height/2));};
addEventListener('pagehide',()=>{if(url)URL.revokeObjectURL(url);});
})();
